use std::pin::Pin;

pub use tokio::io::AsyncRead;
use tokio::io::{AsyncWrite, AsyncWriteExt as _, BufReader};

#[allow(clippy::double_must_use)] // generated by async_trait
#[async_trait::async_trait]
pub trait PacketSender {
    async fn send(&mut self, data: &[u8]) -> anyhow::Result<()>;
}

pub type BoxedPacketReceiver = Pin<Box<dyn AsyncRead + Send>>;
pub type BoxedPacketSender = Box<dyn PacketSender + Send>;

#[async_trait::async_trait]
impl<T: AsyncWrite + Send + Unpin> PacketSender for T {
    async fn send(&mut self, data: &[u8]) -> anyhow::Result<()> {
        self.write_all(data).await?;
        Ok(())
    }
}

#[allow(clippy::double_must_use)] // generated by async_trait
#[async_trait::async_trait]
pub trait ConnectionFactory: Send {
    fn tcp_port(&self) -> Option<u16> {
        None
    }

    async fn connect(self: Box<Self>) -> anyhow::Result<(BoxedPacketReceiver, BoxedPacketSender)>;
}

pub type BoxedConnectionFactory = Box<dyn ConnectionFactory>;

struct TcpConnectionFactory {
    port: u16,
}

#[async_trait::async_trait]
impl ConnectionFactory for TcpConnectionFactory {
    fn tcp_port(&self) -> Option<u16> {
        Some(self.port)
    }

    async fn connect(self: Box<Self>) -> anyhow::Result<(BoxedPacketReceiver, BoxedPacketSender)> {
        let port = self.port;
        let tcp_listener = tokio::net::TcpListener::bind(format!("127.0.0.1:{port}")).await?;
        eprintln!("Awaiting for incoming GDB Remote connection on port {port}");
        let (tcp_stream, _addr) = tcp_listener.accept().await?;
        eprintln!("GDB Remote connection accepted!");
        let (read, write) = tcp_stream.into_split();
        let read = BufReader::new(read);
        let rx: BoxedPacketReceiver = Box::pin(read);
        let tx: BoxedPacketSender = Box::new(write);
        anyhow::Ok((rx, tx))
    }
}

struct PremadeConnectionFactory {
    sender: BoxedPacketSender,
    receiver: BoxedPacketReceiver,
    on_constructed: Box<dyn FnOnce() + Send>,
}

#[async_trait::async_trait]
impl ConnectionFactory for PremadeConnectionFactory {
    async fn connect(self: Box<Self>) -> anyhow::Result<(BoxedPacketReceiver, BoxedPacketSender)> {
        (self.on_constructed)();
        anyhow::Ok((self.receiver, self.sender))
    }
}

pub fn tokio_tcp_connection(port: u16) -> BoxedConnectionFactory {
    Box::new(TcpConnectionFactory { port })
}

pub fn premade_connection(
    sender: BoxedPacketSender,
    receiver: BoxedPacketReceiver,
    on_constructed: impl FnOnce() + Send + 'static,
) -> BoxedConnectionFactory {
    Box::new(PremadeConnectionFactory {
        sender,
        receiver,
        on_constructed: Box::new(on_constructed),
    })
}
